// Extract order data from incoming payload
const body = $input.first().json.body || $input.first().json;

const token = body.token || '#TAJ-???';
const orderId = body.order_id || 'TAJ-UNKNOWN';
const customerName = body.customer?.name || body.customerName || 'Customer';
const phone = body.customer?.phone || body.phone || 'Unknown';
const items = body.items || [];
const totalFormatted = body.total_formatted || `₹${body.total || 0}`;
const paymentMethod = body.payment_method || 'CASH_ON_PICKUP';
const pickupWindow = body.pickup_window || '10–12 Mins';
const freeGift = body.free_gift ? body.free_gift.name : null;

// Format checklist for Kitchen Staff
let itemListStr = items.map(it => `• *${it.quantity}x* ${it.name} (${it.code || 'B'})`).join('\n');
if (freeGift) {
  itemListStr += `\n• 🎁 *FREE GIFT:* ${freeGift} (₹0)`;
}

const staffNotificationMessage = `🍗 *TAJ HOTEL MADURAI - NEW KITCHEN ORDER*\n` +
  `🎟️ *TOKEN:* ${token} _(${pickupWindow})_\n` +
  `🆔 *Order ID:* ${orderId}\n` +
  `👤 *Customer:* ${customerName} (📱 +${phone})\n` +
  `💵 *Payment:* ${paymentMethod} — *Total: ${totalFormatted}*\n\n` +
  `📋 *ITEMS TO PACK:*\n` +
  itemListStr + `\n\n` +
  `⚡ *Status:* Express Counter Pickup ready in ${pickupWindow}!`;

return [{
  json: {
    token,
    orderId,
    customerName,
    phone,
    items,
    totalFormatted,
    paymentMethod,
    pickupWindow,
    freeGift,
    staffNotificationMessage,
    receivedAt: new Date().toISOString()
  }
}];
